import {SUPABASE_URL,SUPABASE_PUBLISHABLE_KEY} from './config.mjs';
import {signIn,signUp,signOut,loadAll} from './store.mjs';
import {icon} from './icons.mjs';

export function showSettings({state,render,toast}){
  const root=document.querySelector('#settings-content');if(!root)return;
  root.innerHTML=`<section class="section-card"><h2>${icon('database')} Banco de dados</h2><p>O projeto Supabase está configurado. Falta apenas criar as tabelas uma vez e entrar na sua conta.</p><div class="notice blue"><strong>Projeto conectado</strong><br>${SUPABASE_URL.replace('https://','')}<br><span class="small">Chave pública ${SUPABASE_PUBLISHABLE_KEY.slice(0,18)}…</span></div><div class="form-actions"><a href="/schema.sql" download="mapa-leads-schema.sql"><button>${icon('download')}Baixar schema.sql</button></a><a href="https://supabase.com/dashboard/project/olhytsvxisvlmilphxic/sql/new" target="_blank" rel="noopener noreferrer"><button>${icon('external')}Abrir editor SQL</button></a></div><ol class="setup-steps"><li>Abra o editor SQL do projeto.</li><li>Cole o conteúdo do arquivo <strong>schema.sql</strong> e clique em “Run”.</li><li>Volte ao CRM e crie sua conta abaixo.</li></ol></section><section class="section-card" id="account-card"><h2>${icon('shield')} Acesso ao CRM</h2>${state.user?`<p>Sessão ativa como <strong>${state.user.email||'usuário autenticado'}</strong>.</p><div class="form-actions"><button id="reload">${icon('database')}Recarregar base</button><button id="logout" class="danger">${icon('logout')}Sair</button></div>`:`<p>Use um e-mail e senha para manter seus leads protegidos pelas regras do banco.</p><form id="auth-form"><div class="form-grid"><div class="field"><label for="auth-email">E-mail</label><input id="auth-email" type="email" autocomplete="email" required placeholder="voce@empresa.com"></div><div class="field"><label for="auth-password">Senha</label><input id="auth-password" type="password" autocomplete="current-password" minlength="6" required placeholder="Mínimo de 6 caracteres"></div></div><div class="form-actions"><button class="primary" type="submit" name="mode" value="signin">Entrar</button><button type="submit" name="mode" value="signup">Criar conta</button></div></form>`}</section>`;
  const form=root.querySelector('#auth-form');if(form)form.onsubmit=async e=>{e.preventDefault();const btn=e.submitter,mode=btn.value,email=root.querySelector('#auth-email').value.trim(),password=root.querySelector('#auth-password').value;root.querySelectorAll('button').forEach(b=>b.disabled=true);try{if(mode==='signup'){const data=await signUp(state,email,password);if(!data.session)toast('Conta criada. Confira seu e-mail para confirmar o acesso.');else{toast('Conta criada e conectada.');render();}}else{await signIn(state,email,password);toast('Supabase conectado.');render();}}catch(err){toast(err.message);}finally{root.querySelectorAll('button').forEach(b=>b.disabled=false);}};
  root.querySelector('#logout')?.addEventListener('click',async()=>{await signOut(state);toast('Sessão encerrada.');render();});
  root.querySelector('#reload')?.addEventListener('click',async()=>{try{await loadAll(state);toast('Base atualizada.');}catch(err){toast(err.message);}});
}
